CREATE OR REPLACE FUNCTION public.tms_import_cte(xml_text text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE doc xml; fiscal_key text; number_text text; fiscal_total numeric; refs text[]; linked integer; base_total numeric; weight_total numeric; all_base boolean; all_weight boolean; method text; conference jsonb; tolerance numeric:=2; percent numeric; allocations jsonb:='[]'; remainder integer; cents bigint; share bigint; used bigint:=0; r public.app_records%ROWTYPE; oc public.app_records%ROWTYPE; cte_data jsonb; next_data jsonb; doc_id text; invoice_id text; customer text; compare_status text; BEGIN IF NOT public.tms_module('/coletas') THEN RAISE EXCEPTION 'Sem permissão para importar CT-e'; END IF; doc:=xmlparse(document xml_text); fiscal_key:=regexp_replace((xpath('string(//*[local-name()="infCte"]/@Id)',doc))[1]::text,'^CTe',''); number_text:=(xpath('string(//*[local-name()="ide"]/*[local-name()="nCT"])',doc))[1]::text; fiscal_total:=((xpath('string(//*[local-name()="vPrest"]/*[local-name()="vTPrest"])',doc))[1]::text)::numeric; IF fiscal_key !~ '^\d{44}$' OR fiscal_total<=0 THEN RAISE EXCEPTION 'CT-e inválido'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('cte:'||fiscal_key,0)); IF EXISTS(SELECT 1 FROM public.app_records WHERE collection='cteDocuments' AND data->>'chave'=fiscal_key) THEN RETURN jsonb_build_object('status','duplicado','chave',fiscal_key); END IF; IF EXISTS(SELECT 1 FROM public.app_records WHERE collection='orders' AND data->>'cteChave'=fiscal_key) THEN RETURN jsonb_build_object('status','historico_pendente','chave',fiscal_key,'motivo','CT-e histórico exige regularização confirmada'); END IF; SELECT array_agg(DISTINCT v::text) INTO refs FROM unnest(xpath('//*[local-name()="infNFe"]/*[local-name()="chave"]/text()',doc)) v; IF cardinality(refs) IS NULL OR cardinality(refs)=0 THEN RETURN jsonb_build_object('status','pendente','chave',fiscal_key,'motivo','CT-e sem referências identificáveis de NF-e'); END IF; PERFORM 1 FROM public.app_records WHERE collection='orders' AND data->>'chaveNFe'=ANY(refs) ORDER BY id FOR UPDATE; SELECT count(*),sum(coalesce((data->>'valorFrete')::numeric,0)),sum(coalesce((data->>'peso')::numeric,0)),bool_and(coalesce((data->>'valorFrete')::numeric,0)>0 AND coalesce(data->>'origemValor','')<>''),bool_and(coalesce((data->>'peso')::numeric,0)>0),min(data->>'clienteNome') INTO linked,base_total,weight_total,all_base,all_weight,customer FROM public.app_records WHERE collection='orders' AND data->>'chaveNFe'=ANY(refs); IF linked<>cardinality(refs) THEN RETURN jsonb_build_object('status','pendente','chave',fiscal_key,'motivo','NF-e correspondente ainda não importada'); END IF; SELECT coalesce((data->'value'->>'toleranciaDivergenciaPercent')::numeric,2) INTO tolerance FROM public.app_records WHERE collection='config' AND id='__doc'; tolerance:=coalesce(tolerance,2); percent:=CASE WHEN all_base THEN (fiscal_total-base_total)/base_total*100 ELSE NULL END; compare_status:=CASE WHEN NOT all_base THEN 'pendente' WHEN abs(percent)>tolerance THEN 'divergente' ELSE 'conferido' END; conference:=jsonb_build_object('status',compare_status,'base',CASE WHEN all_base THEN base_total ELSE 0 END,'fiscal',fiscal_total,'percent',percent,'tolerance',tolerance); method:=CASE WHEN all_base THEN 'frete' WHEN all_weight THEN 'peso' ELSE 'pendente' END; cents:=round(fiscal_total*100); IF method<>'pendente' THEN FOR r IN SELECT * FROM public.app_records WHERE collection='orders' AND data->>'chaveNFe'=ANY(refs) ORDER BY id LOOP share:=floor(cents * CASE WHEN all_base THEN (r.data->>'valorFrete')::numeric/base_total ELSE (r.data->>'peso')::numeric/weight_total END); used:=used+share; allocations:=allocations||jsonb_build_array(jsonb_build_object('orderId',r.id,'cents',share)); END LOOP; remainder:=cents-used; SELECT jsonb_agg(jsonb_build_object('orderId',a->>'orderId','value',((a->>'cents')::numeric+CASE WHEN ordinal<=remainder THEN 1 ELSE 0 END)/100)) INTO allocations FROM jsonb_array_elements(allocations) WITH ORDINALITY AS t(a,ordinal); END IF; doc_id:='CTE-'||fiscal_key; invoice_id:='REC-CTE-'||fiscal_key; cte_data:=jsonb_build_object('id',doc_id,'chave',fiscal_key,'numero',number_text,'valorFiscal',fiscal_total,'xmlOriginal',xml_text,'nfChaves',to_jsonb(refs),'orderIds',(SELECT jsonb_agg(id) FROM public.app_records WHERE collection='orders' AND data->>'chaveNFe'=ANY(refs)),'rateio',jsonb_build_object('method',method,'allocations',allocations),'conferencia',conference,'criadoEm',now()); INSERT INTO public.app_records(collection,id,data,atualizado_por) VALUES('cteDocuments',doc_id,cte_data,auth.uid()); INSERT INTO public.app_records(collection,id,data,atualizado_por) VALUES('invoices',invoice_id,jsonb_build_object('id',invoice_id,'cteChave',fiscal_key,'numero','CTe '||number_text,'clienteNome',customer,'emissao',to_char(current_date,'YYYY-MM-DD'),'competencia',to_char(current_date,'YYYY-MM-DD'),'vencimento',to_char(current_date+30,'YYYY-MM-DD'),'valor',fiscal_total,'status','aberta','tipo','CTe'),auth.uid()); FOR r IN SELECT * FROM public.app_records WHERE collection='orders' AND data->>'chaveNFe'=ANY(refs) ORDER BY id LOOP next_data:=r.data||jsonb_build_object('cteChave',coalesce(r.data->>'cteChave',fiscal_key),'cteNumero',coalesce(r.data->>'cteNumero',number_text),'cteChaves',coalesce(r.data->'cteChaves',CASE WHEN r.data->>'cteChave' IS NOT NULL THEN jsonb_build_array(r.data->>'cteChave') ELSE '[]'::jsonb END)||jsonb_build_array(fiscal_key),'conferencia',conference,'divergenciaPercent',percent,'atualizadoEm',now(),'timeline',coalesce(r.data->'timeline','[]'::jsonb)||jsonb_build_array(jsonb_build_object('quando',now(),'autor',auth.uid(),'tipo','sistema','texto','CT-e '||number_text||' vinculado; conferência '||compare_status||'; rateio '||method))); IF method<>'pendente' THEN next_data:=next_data||jsonb_build_object('cteValor',coalesce((r.data->>'cteValor')::numeric,0)+(SELECT (a->>'value')::numeric FROM jsonb_array_elements(allocations) a WHERE a->>'orderId'=r.id)); END IF; IF coalesce(r.data->>'stage','') NOT IN ('em_viagem','entregue','ocorrencia') AND compare_status<>'pendente' THEN next_data:=next_data||jsonb_build_object('stage',CASE WHEN compare_status='conferido' THEN 'cte_ok' ELSE 'cte_divergente' END); END IF; UPDATE public.app_records SET data=next_data,version=version+1,atualizado_em=now(),atualizado_por=auth.uid() WHERE collection='orders' AND id=r.id; INSERT INTO public.tms_audit(collection,record_id,author,reason,previous_version,new_version) VALUES('orders',r.id,auth.uid(),'Importação CT-e transacional com rateio no servidor',r.version,r.version+1); END LOOP; INSERT INTO public.tms_audit(collection,record_id,author,reason,previous_version,new_version) VALUES('cteDocuments',doc_id,auth.uid(),'CT-e único e receita vinculada',0,1); UPDATE public.email_xml_inbox SET status='importado',importado_em=now() WHERE chave=fiscal_key AND tipo='cte'; FOR oc IN SELECT * FROM public.app_records WHERE collection='ordensColeta' AND data->>'modelo'='v2' AND data->>'status' IN ('emitida','em_coleta','coletada') AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(data->'orderIds') nid JOIN public.app_records o2 ON o2.collection='orders' AND o2.id=nid AND o2.data->>'cteChave'=fiscal_key) FOR UPDATE LOOP UPDATE public.app_records SET version=oc.version+1,atualizado_em=now(),atualizado_por=auth.uid(),data=oc.data||jsonb_build_object('status','aguardando_viagem','atualizadoEm',now(),'historico',coalesce(oc.data->'historico','[]'::jsonb)||jsonb_build_array(jsonb_build_object('quando',now(),'autor','sistema','tipo','status','texto','CT-e '||number_text||' vinculado · aguardando início de viagem'))) WHERE collection='ordensColeta' AND id=oc.id; INSERT INTO public.tms_audit(collection,record_id,author,reason,previous_version,new_version) VALUES('ordensColeta',oc.id,auth.uid(),'CT-e vinculado: aguardando início de viagem',oc.version,oc.version+1); END LOOP; RETURN jsonb_build_object('status','importado','chave',fiscal_key,'notas',linked,'conferencia',compare_status,'rateio',method); END $$;